from collections import defaultdict, deque
nodes = {"N1", "N2", "N3", "N4", "N5"}
links = [("L1", "N1", "N2", False), ("L2", "N2", "N3", True),
         ("L3", "N3", "N1", True), ("L4", "N4", "N9", False)]
errors = [l[0] for l in links if l[1] not in nodes or l[2] not in nodes]
g = defaultdict(list)
for lid, a, b, one in links:
    if lid in errors:
        continue
    g[a].append(b)
    if not one:
        g[b].append(a)
seen, q = {"N1"}, deque(["N1"])
while q:
    for nx in g[q.popleft()]:
        if nx not in seen:
            seen.add(nx)
            q.append(nx)
print("노드 없는 링크:", errors)
print("N1 에서 못 가는 노드:", sorted(nodes - seen))
# 출력
# 노드 없는 링크: ['L4']
# N1 에서 못 가는 노드: ['N4', 'N5']
